// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool okFallback, ) = address(c).call{value: 1 ether}("");
        assertTrue(okFallback);

        vm.prank(nonOwner);
        (bool okWithdrawAll, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(!okWithdrawAll);
    }
}
